WITH kept_keys AS (SELECT method FROM payments EXCEPT ALL SELECT method FROM payments WHERE HOUR(paid_at) BETWEEN 9 AND 17), reconciled AS (SELECT s.* FROM payments s INNER JOIN kept_keys k ON s.method = k.method) SELECT CASE WHEN amount >= 1690 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, method, COUNT(*) AS cnt, STDDEV_SAMP(amount) AS amount_stddev, ROUND(AVG(amount), 2) AS avg_amount, PERCENT_RANK() OVER (PARTITION BY CASE WHEN amount >= 1690 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY COUNT(*) DESC) AS cnt_percent_rank FROM reconciled GROUP BY CASE WHEN amount >= 1690 THEN 'PREMIUM' ELSE 'STANDARD' END, method ORDER BY amount_tier DESC
